package com.example.sakuraevents

/**
 * Represents a lottery that can generate a list of winners based on the capacity of the lottery.
 *
 * A lottery has a capacity, a start time, an end time, a lis of campsites, and a list of winners.
 *
 * @property capacity The capacity of the lottery.
 * @property start_time The start time of the lottery.
 * @property end_time The end time of the lottery.
 * @property campsites_list The list of campsites that can be entered into the lottery.
 * @property winners_list The list of winners that have been generated by the lottery.
 */


class Lottery(private var capacity: Int = 0,
              private var start_time: String = "",
              private var end_time: String = "",
              private var winners_list: MutableList<Entrants> = mutableListOf<Entrants>(),
              private var campsites_list: MutableList<Campsite> = mutableListOf<Campsite>()
)
{
    /**
     * Generates a list of winners from entrants of the waitlist based on the capacity of the lottery at the start time
     * and stop it at the end time.
     *
     *
     * @return A list of Entrants that have won the lottery.
     */


    fun receiveCapacity(new_cap: Int) {
        capacity = new_cap
    }

    fun receiveStartTime(new_start_time: String) {
        start_time = new_start_time
    }

    fun receiveEndTime(new_end_time: String) {
        end_time = new_end_time
    }

    fun getWinnerList(winners_list: MutableList<Entrants>) {}

}